const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Cambodia regions (north/south split at ~12.5°N)
  const cambodia = ee.Geometry.Rectangle([102.3, 10.4, 107.6, 14.7]);
  const northCambodia = ee.Geometry.Rectangle([102.3, 12.5, 107.6, 14.7]);
  const southCambodia = ee.Geometry.Rectangle([102.3, 10.4, 107.6, 12.5]);

  // 2. Date range
  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // 3. Load MODIS fire product
  let fireCol = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(cambodia)
    .select('FireMask');

  const colSize = fireCol.size().getInfo();
  console.log(`Total images found: ${colSize}`);

  if (colSize === 0) {
    // Try VIIRS as fallback
    fireCol = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
      .filterDate(startDate, endDate)
      .filterBounds(cambodia);

    const viirSize = fireCol.size().getInfo();
    console.log(`VIIRS images found: ${viirSize}`);

    if (viirSize === 0) {
      console.log('No fire detection data available.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Process fire detections
  // For MODIS: FireMask values 7,8,9 indicate fire
  const fireImage = fireCol.map(function(img) {
    const fireMask = img.gte(7).and(img.lte(9));
    return fireMask.selfMask();
  }).sum();

  // 5. Count fire pixels in north and south
  const northCount = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northCambodia,
    scale: 1000,
    maxPixels: 1e9
  }).values().get(0);

  const southCount = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southCambodia,
    scale: 1000,
    maxPixels: 1e9
  }).values().get(0);

  const northVal = northCount.getInfo();
  const southVal = southCount.getInfo();

  console.log(`Northern Cambodia fire detections: ${northVal}`);
  console.log(`Southern Cambodia fire detections: ${southVal}`);

  // 6. Validation and answer
  if (northVal === null || southVal === null) {
    console.log('Calculation failed - null result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (northVal === 0 && southVal === 0) {
    console.log('No fire pixels detected in either region.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (northVal > southVal) {
    console.log('Northern Cambodia had more active fires.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Southern Cambodia had more or equal active fires.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
